package com.example.appointment.adapter.in.rest;
import com.example.appointment.application.*; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(NotFoundException.class) ProblemDetail notFound(RuntimeException e){return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND,e.getMessage());} @ExceptionHandler(ConflictException.class) ProblemDetail conflict(RuntimeException e){return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT,e.getMessage());} @ExceptionHandler(PartnerUnavailableException.class) ProblemDetail partner(RuntimeException e){return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_GATEWAY,"Partner Integration Layer is unavailable");} @ExceptionHandler({IllegalArgumentException.class,MethodArgumentNotValidException.class}) ProblemDetail bad(Exception e){return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,"Invalid request");} }
